import{_ as o,a0 as m,w as p,s,ao as n,I as i,x as t,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在Linux上安裝Telegram Messenger應用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux上安裝Telegram Messenger應用 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux上安裝Telegram Messenger應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux上安裝Telegram Messenger應用 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150324 How to Install Telegram Messenger Application on Linux","title":"如何在Linux上安裝Telegram Messenger應用","tag":"201504","desc":""},"relativePath":"201504/20150324 How to Install Telegram Messenger Application on Linux.md","filePath":"[post].md"}'),g={name:"201504/20150324 How to Install Telegram Messenger Application on Linux.md"};function T(u,e,d,w,x,c){const l=m("Link");return p(),s("div",null,[e[17]||(e[17]=n('<h1 id="如何在linux上安裝telegram-messenger應用" tabindex="-1">如何在Linux上安裝Telegram Messenger應用 <a class="header-anchor" href="#如何在linux上安裝telegram-messenger應用" aria-label="Permalink to “如何在Linux上安裝Telegram Messenger應用”">​</a></h1><p>Telegram是和whatsapp類似的及時通訊應用。它有一個龐大的用户羣，並且很多能和其他通訊應用區分開來的特性。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Install-Telegram-in-Linux.png" alt="在Linux上安裝Telegram"> Telegram Messenger for Linux</p><p>這篇文章讓你瞭解Telegram應用，以及在Linux Box上的詳細安裝命令。</p><h4 id="telegram的特性" tabindex="-1">Telegram的特性 <a class="header-anchor" href="#telegram的特性" aria-label="Permalink to “Telegram的特性”">​</a></h4><ul><li>支持移動設備</li><li>有桌面版本</li><li>第三方開發者可以訪問Telegram的應用程序接口(API)。</li><li>支持Android, iphone/ipad, Windows Phone, Web-Version, PC, Mac 和 Linux。</li><li>以上應用支持高度加密和自銷燬信息。</li><li>可以讓你從多種設備和平台查看你的信息。</li><li>整體的處理和消息傳送都非常快</li><li>為了安全和效率，在全球有分佈式服務器</li><li>開放的API和自由協議</li><li>沒有廣告，沒有認購費用。-永久免費</li><li>功能強大-沒有媒體和聊天限制</li><li>多種安全措施使其免受黑客侵害</li><li>在羣組中回覆特定信息。使用@username提醒羣組裏的多個用户</li></ul><h4 id="為什麼使用telegram" tabindex="-1">為什麼使用Telegram? <a class="header-anchor" href="#為什麼使用telegram" aria-label="Permalink to “為什麼使用Telegram?”">​</a></h4><p>在像WhatsApp以及其他及時通訊應用都提供了幾乎同樣的功能的情況下，為什麼要選擇Telegram？</p><p>第三方開發者可以使用API這一點就足夠了。更多PC的可用性意味着你不必再糾結在你的移動設備上打字，你可以使用你的PC，這樣更具有可用性。</p><p>另外，支持連接遠程地點，協作-多達200個成員的羣組，在所有設備上同步，發送各種類型的文件，信息加密，自毀信息，在雲上存儲媒體，基於完全可用API構建自己的工具。</p><p><strong>測試環境</strong></p><p>我們使用Debian GNU/Linux, x86_64結構測試，所有的步驟都非常順利。以下是我們的詳細步驟。</p><h3 id="在linux上安裝telegram-messenger" tabindex="-1">在Linux上安裝Telegram Messenger <a class="header-anchor" href="#在linux上安裝telegram-messenger" aria-label="Permalink to “在Linux上安裝Telegram Messenger”">​</a></h3>',13)),i("p",null,[e[1]||(e[1]=t("首先去Telegram的官方網站，下載Linux系統版本的Telegram源碼包(",-1)),a(l,{href:"https://tdesktop.com/linux"},{default:r(()=>[...e[0]||(e[0]=[t("tsetup.0.7.23.tar.xz",-1)])]),_:1}),e[2]||(e[2]=t(")，你也可以使用下面的wget命令直接下載。",-1))]),e[18]||(e[18]=n(`<pre><code># wget https://updates.tdesktop.com/tlinux/tsetup.0.7.23.tar.xz
</code></pre><p>下載好安裝包後，解壓安裝包，並從當前目錄進入解壓後的文件夾。</p><pre><code># tar -xf tsetup.0.7.23.tar.xz 
# cd Telegram/
</code></pre><p>然後，如下所示，在命令列中執行二進制文件‘Telegram’.</p><pre><code># ./Telegram
</code></pre><ol><li>第一個界面， 點擊 “START MESSAGING”.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Start-Messaging.jpeg" alt="開始安裝"> 開始安裝</p><ol start="2"><li>輸入你的手機號碼，點擊&quot;Next&quot;。如果在這之前你沒有註冊過Telegram，使用和之前輸入相同的號碼你會看到警告説你還沒有Telegram賬户。點擊“Register Here”。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Register.png" alt="註冊Telegram"> 註冊Telegram</p><ol start="3"><li>提交你的手機號碼之後，Telegram很快會給你發送一個驗證碼。你需要輸入它。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Verfication-Code.png" alt="Telegram驗證碼"> Telegram驗證碼</p><ol start="4"><li>輸入你的姓名，暱稱並點擊“SIGN UP”.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Enter-Account-Details.jpeg" alt="輸入賬户詳細信息"> 輸入賬户詳細信息</p><ol start="5"><li>新建賬户之後，我看到這個界面。一切準備就緒，儘管我對Telegram還不熟悉。這個界面真的很簡潔。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Interface.jpeg" alt="Telegram界面"> Telegram界面</p><ol start="6"><li>點擊新建聯繫人，輸入他們的姓名和手機號碼，完成後點擊新建。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Add-New-Telegram-Contact.png" alt="新建Telegram聯繫人"> 新建Telegram聯繫人</p><ol start="7"><li>如果Telegram中還沒有你輸入的聯繫人，你會收到一個提示信息，當這個聯繫人加入Telegram的時候Telegram會通知你。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Contact-Notification.jpeg" alt="Telegram聯繫人提示"> Telegram聯繫人提示</p><ol start="8"><li><p>當聯繫人加入Telegram的時候，你會收到信息(類似彈出提示)顯示[YOUR_CONTACT]加入了Telegram。</p></li><li><p>在Linux系統上正式的聊天窗口。很好的體驗…</p></li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Contact-Join-Message.jpeg" alt="聯繫人加入Telegram消息"> 聯繫人加入Telegram消息</p><ol start="10"><li>同時，我試着在我的Android移動設備上發送信息，兩者之間界面非常相似。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Mobile-Interface.png" alt="移動版Telegram界面"> 移動版Telegram界面</p><ol start="11"><li>Telegram設置頁面. 你有很多可以配置的選項.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Settings.png" alt="設置Telegram"> 設置Telegram</p><ol start="12"><li>關於Telegram.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/About-Telegram.jpeg" alt="關於Telegram"> 關於Telegram</p><h4 id="有趣的幾點" tabindex="-1">有趣的幾點 <a class="header-anchor" href="#有趣的幾點" aria-label="Permalink to “有趣的幾點”">​</a></h4><ul><li>Telegram使用MTProto移動協議</li><li>一開始在2013年(8月14號)發佈iPhone版</li><li>驚人項目背後的人物:Pavel and Nikolai Durov..</li></ul><p>就是這些了。我還會為大家帶來你們喜歡閲讀的其它有趣文章。很高興能代表Tecmint，感謝我們尊貴的讀者以及使得我們通過不斷的自我提升走到這裏的批評者。保持聯繫！繼續評論。如果你關注我們那就請分享吧。</p>`,30)),i("ul",null,[i("li",null,[a(l,{href:"https://telegram.org/"},{default:r(()=>[...e[3]||(e[3]=[t("https://telegram.org/",-1)])]),_:1})])]),e[19]||(e[19]=i("hr",null,null,-1)),i("p",null,[e[5]||(e[5]=t("via: ",-1)),a(l,{href:"http://www.tecmint.com/install-telegram-in-linux/"},{default:r(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/install-telegram-in-linux/",-1)])]),_:1})]),i("p",null,[e[9]||(e[9]=t("作者：",-1)),a(l,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...e[6]||(e[6]=[t("Avishek Kumar",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),a(l,{href:"https://github.com/ictlyh"},{default:r(()=>[...e[7]||(e[7]=[t("ictlyh",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),a(l,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[8]||(e[8]=[t("Caroline",-1)])]),_:1})]),i("p",null,[e[14]||(e[14]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),a(l,{href:"http://linux.cn/"},{default:r(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const C=o(g,[["render",T]]);export{L as __pageData,C as default};
